setup.test_shapes.py:
import unittest
from shapes import circle_area, rectangle_area


class TestShapes(unittest.TestCase):
    def test_rectangle(self):
        self.assertEqual(rectangle_area(2, 3), 6)

    def test_circle(self):
        self.assertAlmostEqual(circle_area(1), 3.141592653589793)
        self.assertAlmostEqual(circle_area(2), 12.566370614359172)


if __name__ == "__main__":
    unittest.main()

